#include "native_helpers.hpp"

inline bool has_field(const J&j,const std::string&k){return j.object.count(k)!=0;}
inline bool value_present(const J&j,const std::string&k){return has_field(j,k)&&j.at(k).scalar!="null";}
std::vector<J> lines(const files::path&path){std::ifstream f(path);require(bool(f),"Cannot read JSONL");std::vector<J> result;std::string text;while(std::getline(f,text)){if(text.find_first_not_of(" \t\r")==std::string::npos)continue;Parser p;p.s=text;auto j=p.value();p.ws();require(p.i==p.s.size(),"Trailing JSONL bytes");result.push_back(std::move(j));}return result;}
struct Fixture {std::string id,split;P point;uint64_t d;};
std::vector<Fixture> verify_fixtures(const files::path&dir,const Instance&instance){
 auto receipt=read_json((dir/"generator_receipt.json").string()),sidecar=read_json((dir/"validation_sidecar.json").string());require(receipt.at("status").scalar=="PASS"&&num(receipt.at("seed"))==202610128301ULL,"Wrong generator receipt seed/status");check_modulus(receipt);require(num(receipt.at("subgroup_order"))==instance.r&&point(receipt.at("generator"))==instance.g,"Generator identity mismatch");require(digest(dir/"validation_sidecar.json")==receipt.at("validation_sidecar_sha256").scalar,"Sidecar hash mismatch");
 const auto&targets=receipt.at("targets").array;const auto&side=sidecar.at("entries").array;require(targets.size()==8&&side.size()==8,"Wrong fixture count");std::vector<Fixture> out;auto excluded=instance.excluded_orbits;SplitMix64 rng{202610128301ULL};uint64_t bound=instance.r-1,threshold=(uint64_t(0)-bound)%bound,range_rejects=0,orbit_rejects=0;std::string combined;
 for(size_t i=0;i<8;++i){const auto&t=targets[i];std::string split=i<3?"training":"holdout",id=split+"_"+std::to_string(i<3?i+1:i-2);require(t.at("fixture_id").scalar==id&&t.at("split").scalar==split,"Fixture split/order mismatch");require(side[i].at("fixture_id").scalar==id,"Sidecar fixture order mismatch");P q=point(t.at("point"));require(on(q)&&!q.inf&&mul(instance.r,q).inf,"Fixture curve/subgroup failure");U key=orbit_key(q);require(!excluded.count(key),"Fixture overlaps prior/base/another signed orbit");require(dec(key)==t.at("signed_frobenius_orbit_key_decimal").scalar,"Orbit key mismatch");uint64_t d=uint64_t(num(side[i].at("scalar_validation_only")));require(d>0&&d<instance.r&&point(side[i].at("point"))==q&&mul(d,instance.g)==q,"Sidecar scalar replay failure");
 uint64_t expected_d=0;while(true){auto raw=rng.next();if(raw<threshold){++range_rejects;continue;}auto proposed=raw%bound+1;P candidate=mul(proposed,instance.g);if(excluded.count(orbit_key(candidate))){++orbit_rejects;continue;}expected_d=proposed;break;}require(expected_d==d&&rng.draws==num(t.at("SplitMix64_draw_number")),"SplitMix/rejection reproducibility failure");excluded.insert(key);
 auto file=dir/t.at("point_file").scalar;require(digest(file)==t.at("point_file_sha256").scalar,"Point file digest mismatch");auto row=lines(file);require(row.size()==1&&point(row[0])==q,"Point-only individual file mismatch");if(i>=3)combined+=bytes(file);out.push_back({id,split,q,d});
 }
 require(rng.draws==num(receipt.at("SplitMix64_draws"))&&range_rejects==num(receipt.at("uniform_range_rejections"))&&orbit_rejects==num(receipt.at("excluded_orbit_rejections")),"Generator rejection counts mismatch");require(bytes(dir/"holdout_5_targets.jsonl")==combined&&digest(dir/"holdout_5_targets.jsonl")==receipt.at("holdout_combined_sha256").scalar,"Five-target combined file mismatch");return out;
}
struct CheckedRow{std::string file,arm,status,fixture_id,error,scalar;bool same_instance=false,answer_present=false,replay=false,witness=false,sidecar_after_answer=false;};
int main(int argc,char**argv){try{
 const bool fixtures_only=argc==5&&std::string(argv[1])=="--fixtures-only";require(fixtures_only||argc==5,"usage: check_optimization ARCHIVE FIXTURES COMPLETED_PANEL NEW_RECEIPT; or --fixtures-only ARCHIVE FIXTURES NEW_RECEIPT");files::path archive=argv[fixtures_only?2:1],fixture_dir=argv[fixtures_only?3:2],output=argv[4];require(!files::exists(output),"Refusing existing receipt");auto instance=verify_instance(archive);auto fixtures=verify_fixtures(fixture_dir,instance);
 std::vector<CheckedRow> rows;std::vector<files::path> producer_files,execution_files;size_t answers=0,witnesses=0,rho_rows=0,ic_rows=0,invalid=0;std::ostringstream process_rows;
 if(!fixtures_only){files::path panel=argv[3];require(files::exists(panel),"Panel directory missing");for(const auto&entry:files::recursive_directory_iterator(panel)){if(!entry.is_regular_file())continue;auto name=entry.path().filename().string();if(name=="producer.json"||name=="target.jsonl"||name=="targets.jsonl")producer_files.push_back(entry.path());else if(name=="execution.json")execution_files.push_back(entry.path());}std::sort(producer_files.begin(),producer_files.end());std::sort(execution_files.begin(),execution_files.end());
 for(const auto&file:producer_files){bool ic=file.filename()!="producer.json";std::vector<J> rawrows;try{rawrows=ic?lines(file):std::vector<J>{read_json(file.string())};}catch(const std::exception&e){rows.push_back({file.string(),ic?"IC":"strong_rho","INVALID_JSON","",e.what(),""});++invalid;continue;}
 for(const auto&j:rawrows){CheckedRow row;row.file=file.string();row.arm=ic?"IC":"strong_rho";if(ic)++ic_rows;else ++rho_rows;row.status=has_field(j,"status")?j.at("status").scalar:(value_present(j,"recovered_scalar")?"ANSWER_RECORDED":"NO_ANSWER_RECORDED");try{
 if(!has_field(j,"generator")||!has_field(j,"published_q")){require(!value_present(j,"recovered_scalar"),"Answer lacks generator/Q fields");rows.push_back(row);continue;}
 require(point(j.at("generator"))==instance.g&&num(j.at("n"))==83&&num(j.at("a"))==1,"Producer curve/G mismatch");P q=point(j.at("published_q"));auto it=std::find_if(fixtures.begin(),fixtures.end(),[&](const Fixture&f){return f.point==q;});require(it!=fixtures.end(),"Producer Q is not one of eight frozen fixtures");row.fixture_id=it->id;row.same_instance=true;
 if(ic){if(has_field(j,"target"))require(point(j.at("target"))==q,"IC target field mismatch");if(has_field(j,"published_fixture_scalar"))require(j.at("published_fixture_scalar").scalar=="null","IC scalar input recorded");}
 else{check_modulus(j);require(num(j.at("subgroup_order"))==instance.r&&num(j.at("lambda"))==instance.lambda,"Strong subgroup/lambda mismatch");if(has_field(j,"public_target_q"))require(point(j.at("public_target_q"))==q,"Strong public target mismatch");if(has_field(j,"known_answer_input"))require(!truth(j.at("known_answer_input")),"Strong scalar input flag");if(has_field(j,"validation_sidecar_opened"))require(!truth(j.at("validation_sidecar_opened")),"Strong opened sidecar");}
 if(!value_present(j,"recovered_scalar")){rows.push_back(row);continue;}row.answer_present=true;row.scalar=j.at("recovered_scalar").scalar;U d=num(j.at("recovered_scalar"));require(mul(d,instance.g)==q,"Independent answer replay failure");row.replay=true;require(d%instance.r==it->d,"After-answer sidecar mismatch");row.sidecar_after_answer=true;
 if(ic){const auto&index=j.at("point_indices").array;require(index.size()==4,"IC lacks four-point witness");P sum;for(size_t k=0;k<4;++k){size_t at=size_t(num(index[k]));require(at<instance.base.size(),"IC witness index outside base");if(has_field(j,"x_codes"))require(instance.base[at].x==num(j.at("x_codes").at(k)),"IC x-code mismatch");sum=add(sum,instance.base[at]);}require(sum==q,"IC witness sum mismatch");if(has_field(j,"pinned_intermediates")){P p01=add(instance.base[size_t(num(index[0]))],instance.base[size_t(num(index[1]))]);P p23=add(instance.base[size_t(num(index[2]))],instance.base[size_t(num(index[3]))]);require(p01.x==num(j.at("pinned_intermediates").at(0))&&p23.x==num(j.at("pinned_intermediates").at(1)),"IC intermediate abscissa mismatch");}require(has_field(j,"group_verified")&&truth(j.at("group_verified")),"IC producer flag false");row.witness=true;++witnesses;}
 else{require(row.status=="PASS_VERIFIED_PUBLIC_TARGET"&&has_field(j,"generic_scalar_replay_verified")&&truth(j.at("generic_scalar_replay_verified")),"Strong producer replay/status false");}++answers;
 }catch(const std::exception&e){row.error=e.what();++invalid;}rows.push_back(row);}
 }
 size_t count=0;for(const auto&path:execution_files){auto j=read_json(path.string());if(count++)process_rows<<",\n";process_rows<<"    {\"file\":"<<qstr(path.string())<<",\"status\":"<<qstr(has_field(j,"status")?j.at("status").scalar:"MISSING_STATUS")<<",\"return_code\":"<<(has_field(j,"return_code")?j.at("return_code").scalar:"null")<<",\"termination_signal\":"<<(has_field(j,"termination_signal")?j.at("termination_signal").scalar:"null")<<"}";}
 }
 std::ostringstream out;out<<"{\n  \"kind\":\"native_n83_optimization_fixture_and_answer_verification\",\n  \"status\":"<<qstr(invalid?"FAIL":(fixtures_only?"PASS_FIXTURES_ONLY":(producer_files.empty()?"NO_PANEL_OUTPUTS":"PASS")))<<",\n  \"scope\":\"Independent arithmetic fixture/answer replay; no performance claim\",\n  \"curve_slug\":\"icv1-f2m83-t6151469093347-9eba6cd5\",\n  \"field_modulus_low_terms\":[0,2,4,7],\n  \"fixture_generation_reproduced\":true,\n  \"training_fixtures_verified\":3,\n  \"holdout_fixtures_verified\":5,\n  \"all_fixture_subgroup_and_scalar_replays\":true,\n  \"all_fixture_signed_orbit_exclusions\":true,\n  \"retained_base_points_and_labels_verified\":99600,\n  \"fixture_manifest_sha256\":"<<qstr(digest(fixture_dir/"generator_receipt.json"))<<",\n  \"validation_sidecar_sha256\":"<<qstr(digest(fixture_dir/"validation_sidecar.json"))<<",\n  \"strong_rows\":"<<rho_rows<<",\n  \"IC_target_rows\":"<<ic_rows<<",\n  \"independent_answer_replays\":"<<answers<<",\n  \"IC_four_point_witnesses\":"<<witnesses<<",\n  \"invalid_rows\":"<<invalid<<",\n  \"rows\":[\n";
 for(size_t i=0;i<rows.size();++i){const auto&r=rows[i];if(i)out<<",\n";out<<"    {\"file\":"<<qstr(r.file)<<",\"arm\":"<<qstr(r.arm)<<",\"producer_status\":"<<qstr(r.status)<<",\"fixture_id\":"<<(r.fixture_id.empty()?"null":qstr(r.fixture_id))<<",\"answer_present\":"<<(r.answer_present?"true":"false")<<",\"scalar\":"<<(r.scalar.empty()?"null":qstr(r.scalar))<<",\"same_exact_instance_and_frozen_point\":"<<(r.same_instance?"true":"false")<<",\"independent_scalar_replay\":"<<(r.replay?"true":"false")<<",\"sidecar_validation_after_answer\":"<<(r.sidecar_after_answer?"true":"false")<<",\"IC_witness_replay\":"<<(r.witness?"true":"false")<<",\"error\":"<<(r.error.empty()?"null":qstr(r.error))<<"}";}
 out<<"\n  ],\n  \"process_dispositions\":[\n"<<process_rows.str()<<"\n  ],\n  \"still_unverified\":[\"Full600-row rank/factor-log transcript\",\"Independent timing/operation reproduction\",\"Second-host/isolation promotion gates\"]\n}\n";create_new(output,out.str());std::cout<<"Native verification: fixtures8; answers="<<answers<<"; ICwitnesses="<<witnesses<<"; invalid="<<invalid<<"\n";return invalid?1:(!fixtures_only&&producer_files.empty()?2:0);
 }catch(const std::exception&e){std::cerr<<"FAIL: "<<e.what()<<"\n";return 1;}}
